$ErrorActionPreference='Stop';$product=Get-CimInstance Win32_ComputerSystemProduct
if($env:COMPUTERNAME -cne 'DESKTOP-O1LP5DG' -or $product.UUID -cne 'C6440689-D11C-4C63-A463-F3722B7DDB69'){throw 'Builder identity mismatch.'}
$thumb='220DD82C37FCF36048D59E4F10113185D81D5DC7';$dir='C:\safeupload-cert';$items=@()
foreach($name in @('SafeUploadTest.pfx','SafeUploadTest.cer')){$path=Join-Path $dir $name;$row=[ordered]@{Path=$path;Exists=(Test-Path -LiteralPath $path -PathType Leaf);Length=$null;CreationUtc=$null;LastWriteUtc=$null;Attributes=$null};if($row.Exists){$f=Get-Item -LiteralPath $path;$row.Length=$f.Length;$row.CreationUtc=$f.CreationTimeUtc.ToString('o');$row.LastWriteUtc=$f.LastWriteTimeUtc.ToString('o');$row.Attributes=$f.Attributes.ToString()};$items += $row}
$publicCer=$null;$publicPath=Join-Path $dir 'SafeUploadTest.cer'
if(Test-Path -LiteralPath $publicPath -PathType Leaf){$pub=New-Object System.Security.Cryptography.X509Certificates.X509Certificate2($publicPath);$stored=Get-Item -LiteralPath ('Cert:\CurrentUser\My\'+$thumb);$storedRsa=[System.Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPublicKey($stored);$fileRsa=[System.Security.Cryptography.X509Certificates.RSACertificateExtensions]::GetRSAPublicKey($pub);$a=$storedRsa.ExportParameters($false);$b=$fileRsa.ExportParameters($false);$publicCer=[ordered]@{Thumbprint=$pub.Thumbprint;Subject=$pub.Subject;Issuer=$pub.Issuer;NotBeforeUtc=$pub.NotBefore.ToUniversalTime().ToString('o');NotAfterUtc=$pub.NotAfter.ToUniversalTime().ToString('o');ExactThumbprintMatch=($pub.Thumbprint -ceq $thumb);ExactPublicRsaModulusAndExponentMatch=([Convert]::ToBase64String($a.Modulus) -ceq [Convert]::ToBase64String($b.Modulus) -and [Convert]::ToBase64String($a.Exponent) -ceq [Convert]::ToBase64String($b.Exponent));PrivateMaterialReadOrExported=$false}}
$stores=@();foreach($storePath in @('Cert:\CurrentUser\My','Cert:\CurrentUser\Root','Cert:\LocalMachine\My','Cert:\LocalMachine\Root')){$found=@(Get-ChildItem -LiteralPath $storePath -ErrorAction SilentlyContinue | Where-Object {$_.Thumbprint -ceq $thumb} | ForEach-Object {[ordered]@{Store=$storePath;Thumbprint=$_.Thumbprint;Subject=$_.Subject;HasPrivateKey=[bool]$_.HasPrivateKey;NotAfterUtc=$_.NotAfter.ToUniversalTime().ToString('o')}});$stores += $found}
[ordered]@{Status='Completed';UTC=[DateTime]::UtcNow.ToString('o');ComputerName=$env:COMPUTERNAME;UUID=$product.UUID;User=[Security.Principal.WindowsIdentity]::GetCurrent().Name;BackupMetadata=$items;PublicCertificate=$publicCer;MatchingCertificateStores=$stores;PfxContentsRead=$false;PrivateMaterialReadOrExported=$false}|ConvertTo-Json -Depth 10 -Compress
